def venstrepunkt(f, a, b, n):
    h = (b - a) / n
    return h * sum(
        f(a + i * h)
        for i in range(n)
    )


def midtpunkt(f, a, b, n):
    h = (b - a) / n
    return h * sum(
        f(a + (i + 0.5) * h)
        for i in range(n)
    )


def f(x):
    return x**2


eksakt = 1 / 3

print(
    "n\t\tVenstrepunkt\tMidtpunkt"
)
print("-" * 50)
for n in [10, 100, 1000]:
    v = venstrepunkt(f, 0, 1, n)
    m = midtpunkt(f, 0, 1, n)
    print(
        f"{n}\t\t"
        f"{abs(v - eksakt):.2e}\t"
        f"{abs(m - eksakt):.2e}"
    )
```

