import numpy as np
from scipy import integrate


def simpson(f, a, b, n):
    if n % 2 != 0:
        n += 1
    h = (b - a) / n
    return (h / 3) * (
        f(a)
        + 4
        * sum(
            f(a + i * h)
            for i in range(
                1, n, 2
            )
        )
        + 2
        * sum(
            f(a + i * h)
            for i in range(
                2, n, 2
            )
        )
        + f(b)
    )


# a) x^5
print("a) Integral av x^5:")
f_a = lambda x: x**5
eksakt_a = 1 / 6

for n in [2, 3, 4]:
    gauss, _ = (
        integrate.fixed_quad(
            f_a, 0, 1, n=n
        )
    )
    print(
        f"Gauss n={n}: feil ="
        f" {abs(gauss - eksakt_a):.2e}"
    )

for n in [4, 10, 100]:
    simp = simpson(f_a, 0, 1, n)
    print(
        f"Simpson n={n}: feil ="
        f" {abs(simp - eksakt_a):.2e}"
    )

# b) cos(x) på [0, pi]
print("\nb) Integral av cos(x):")
f_b = lambda x: np.cos(x)
eksakt_b = 0

for n in [2, 3, 5]:
    gauss, _ = (
        integrate.fixed_quad(
            f_b, 0, np.pi, n=n
        )
    )
    print(
        f"Gauss n={n}: feil ="
        f" {abs(gauss - eksakt_b):.2e}"
    )

# c) sqrt(x) - singulær derivert
print("\nc) Integral av sqrt(x):")
f_c = lambda x: np.sqrt(x)
eksakt_c = 2 / 3

for n in [5, 10, 20, 50]:
    gauss, _ = (
        integrate.fixed_quad(
            f_c, 0, 1, n=n
        )
    )
    print(
        f"Gauss n={n}: feil ="
        f" {abs(gauss - eksakt_c):.2e}"
    )

for n in [10, 100, 1000]:
    simp = simpson(f_c, 0, 1, n)
    print(
        f"Simpson n={n}: feil ="
        f" {abs(simp - eksakt_c):.2e}"
    )
```

Gauss-Legendre er svært effektiv for glatte funksjoner, men begge metoder sliter med singulære deriverte.

**Svar:**
- a) Gauss-Legendre: 3 punkter gir feil $< 10^{-10}$. Simpson har fortsatt feil $3{,}3 \cdot 10^{-9}$ ved $n = 100$.
- b) Gauss-Legendre: 2 punkter er nok.
- c) Ingen av metodene når $10^{-10}$ med verdiene i programmet: Gauss-Legendre med 50 punkter gir feil $8{,}0 \cdot 10^{-7}$, Simpson med $n = 1000$ gir $2{,}6 \cdot 10^{-6}$.

