import numpy as np
from scipy import integrate


# NB: dblquad bruker rekkefølgen
# (y, x)
def f(y, x):
    return np.exp(-(x**2 + y**2))


# Beregn dobbeltintegralet
resultat, feil = (
    integrate.dblquad(
        f, 0, 1, 0, 1
    )
)

print(
    "Dobbeltintegral:"
    f" {resultat:.10f}"
)
print(
    f"Feilestimering:  {feil:.2e}"
)


# Sammenlign med manuell iterert
# integrasjon
def inner_integral(x):
    """Integrerer f over y for
    fast x"""
    result, _ = integrate.quad(
        lambda y: np.exp(
            -(x**2 + y**2)
        ),
        0,
        1,
    )
    return result


resultat_iterert, _ = (
    integrate.quad(
        inner_integral, 0, 1
    )
)
print(
    "Iterert:        "
    f" {resultat_iterert:.10f}"
)


# Manuell 2D Simpson
def simpson_2d(
    f, ax, bx, ay, by, nx, ny
):
    """2D Simpson-integrasjon"""
    hx = (bx - ax) / nx
    hy = (by - ay) / ny

    def simpson_1d(g, a, b, n):
        h = (b - a) / n
        return (h / 3) * (
            g(a)
            + 4
            * sum(
                g(a + i * h)
                for i in range(
                    1, n, 2
                )
            )
            + 2
            * sum(
                g(a + i * h)
                for i in range(
                    2, n, 2
                )
            )
            + g(b)
        )

    def inner(x):
        return simpson_1d(
            lambda y: f(x, y),
            ay,
            by,
            ny,
        )

    return simpson_1d(
        inner, ax, bx, nx
    )


def f_xy(x, y):
    return np.exp(-(x**2 + y**2))


resultat_simpson = simpson_2d(
    f_xy, 0, 1, 0, 1, 20, 20
)
print(
    "Simpson 2D:     "
    f" {resultat_simpson:.10f}"
)
```

